def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opps = []
    prev_bids = []
    rich_pressure = 0
    needy_pressure = 0

    for opp_id, opp in opponents_status.items():
        if not opp.get('alive', False):
            continue
        alive_opps.append(opp)
        if opp.get('budget', 0) >= 120:
            rich_pressure += 1
        if opp.get('hp', 10) <= 4 or opp.get('no_water_days', 0) >= 1:
            needy_pressure += 1
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            prev_bids.append(float(prev.get('bid', 0.0)))

    if not alive_opps:
        return float(min(budget, 8.0))

    max_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    units = supply / float(WATER_REQ)
    tight = units < 2.0
    medium_tight = units < 2.6

    urgency = 0
    if hp <= 2:
        urgency += 4
    elif hp <= 4:
        urgency += 2
    if no_water_days >= 2:
        urgency += 4
    elif no_water_days >= 1:
        urgency += 2
    if tight:
        urgency += 2
    elif medium_tight:
        urgency += 1
    urgency += min(needy_pressure, 2)

    if urgency >= 7:
        target = max(63.0, max_prev + 3.0)
    elif urgency >= 5:
        target = max(52.0, avg_prev + 4.0, max_prev * 0.78)
    elif urgency >= 3:
        if max_prev >= 110:
            target = 24.0
        else:
            target = max(30.0, avg_prev * 0.55 + 4.0)
    else:
        if tight and rich_pressure >= 2 and max_prev >= 80:
            target = 12.0
        elif max_prev >= 110:
            target = 10.0
        elif max_prev >= 80:
            target = 16.0
        else:
            target = 22.0 if medium_tight else 14.0

    if day >= 8:
        target += 6.0
    if budget < 45:
        target = min(target, budget)
    elif budget < 90:
        target = min(target, 0.72 * budget)
    else:
        target = min(target, 0.55 * budget)

    if hp <= 2 or no_water_days >= 2:
        target = max(target, min(budget, 66.0))

    if target < 0:
        target = 0.0
    return float(min(budget, round(target, 2)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context.get('supply', MIN_SUPPLY)
    day = day_context.get('day', 0)

    # Identify alive opponents
    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    # Base bid targets: aim to win enough water cheaply unless I'm in danger
    # Convert supply to an approximate number of water units being contested
    # (We don't know exact allocation mechanics; we use supply to scale aggressiveness.)
    supply_int = int(round(supply))
    # Heuristic: higher supply => lower need to bid aggressively
    supply_factor = 1.0
    if supply_int <= MIN_SUPPLY:
        supply_factor = 1.15
    elif supply_int >= MAX_SUPPLY:
        supply_factor = 0.85

    # Read yesterday bids to infer who tends to overbid
    prev_bids = []
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    # Estimate pressure from yesterday: if someone bid very high, they likely try to secure water
    # Use that to avoid being outbid when I'm also vulnerable.
    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # If I'm low HP, bid closer to the likely winning range.
    hp = my_status.get('hp', 0)
    budget = my_status.get('budget', 0)

    # Conservative cap: never bid more than a fraction of budget.
    # But ensure enough to compete.
    budget_cap = budget

    # Strategy tiers
    if hp <= 1:
        # Critical: bid aggressively but not maximal
        target = DAILY_SALARY * 0.85
    elif hp <= 3:
        # Urgent: bid moderately high if others overbid yesterday
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            target = DAILY_SALARY * 0.70
        else:
            target = DAILY_SALARY * 0.55
    else:
        # Healthy: bid only enough to likely secure water
        if highest_prev_bid >= DAILY_SALARY * 1.20:
            # Someone is very aggressive; slightly increase to avoid being starved
            target = DAILY_SALARY * 0.60
        else:
            target = DAILY_SALARY * 0.45

    # Scale by supply conditions
    target *= supply_factor

    # If yesterday highest bid was extremely high, try to undercut slightly
    if highest_prev_bid > 0:
        if highest_prev_bid >= DAILY_SALARY * 1.00:
            target = min(target, highest_prev_bid * 0.85)

    # Final bid with budget constraints
    bid = target
    if bid > budget_cap:
        bid = budget_cap

    # Ensure non-negative
    if bid < 0:
        bid = 0.0

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], 10.0)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        max_prev = max(yesterday_bids)
        if my_status['hp'] <= 3:
            return min(my_status['budget'], max_prev + 5.0)
        if day_context['supply'] < 18.0:
            return min(my_status['budget'], max_prev + 2.0)
        return min(my_status['budget'], max(20.0, max_prev * 0.8))

    return min(my_status['budget'], 40.0)
